struct TokenBucket : public flight::ReferenceEnabled {
  double last_refill_ms;
  double max_bytes_per_second;
  double tokens;
};

inline flight::Ref<TokenBucket> create_token_bucket(double max_bytes_per_second) {
  return flight::make_ref<TokenBucket>(TokenBucket{.last_refill_ms = flight::Date::now(), .max_bytes_per_second = max_bytes_per_second, .tokens = max_bytes_per_second});
}

inline void refill_tokens(flight::Ref<TokenBucket> bucket) {
  const double now = flight::Date::now();
  const double elapsed = ((now - bucket->last_refill_ms) / 1000.0);
  (bucket->tokens = flight::minimum(bucket->max_bytes_per_second, (bucket->tokens + (elapsed * bucket->max_bytes_per_second))));
  (bucket->last_refill_ms = now);
}

inline double token_bucket_delay_ms(flight::Ref<TokenBucket> bucket, double cost) {
  refill_tokens(bucket);
  if (((cost == 0.0) || (bucket->tokens >= cost))) {
    return 0.0;
  }
  const double deficit = (cost - bucket->tokens);
  return std::ceil(((deficit / bucket->max_bytes_per_second) * 1000.0));
}

inline void consume_tokens(flight::Ref<TokenBucket> bucket, double cost) {
  (bucket->tokens = flight::maximum(0.0, (bucket->tokens - cost)));
}

